'use strict';
let builtinSelection='',builtinSelectionRevision=0;const builtinFaces=new Map();
function builtinFontOptions(){const selected=builtinSelection||els.fontChoice.value;const group=document.createElement('optgroup');group.label='Included fonts ('+BUILTIN_FONTS.length+')';for(const f of BUILTIN_FONTS){const option=document.createElement('option');option.value='builtin:'+f.file;const duplicates=BUILTIN_FONTS.filter(v=>v.name===f.name).length>1;option.textContent=f.name.trim()+(duplicates?' · '+f.file.split('.').pop().toUpperCase():'');group.appendChild(option)}const standard=document.createElement('option');standard.value='system';standard.textContent='System · Impact';els.fontChoice.prepend(group);els.fontChoice.prepend(standard);els.fontChoice.style.display='';els.fontChoice.setAttribute('aria-label','Lettering font');els.fontChoice.value=selected||'system';els.fontName.style.display='';els.fontName.textContent=BUILTIN_FONTS.length+' included fonts'+(customFontRecords.length?' + '+customFontRecords.length+' uploaded':'');}
const beforeBuiltinUI=updateCustomFontUi;updateCustomFontUi=function(active){beforeBuiltinUI(active);builtinFontOptions()};
async function chooseBuiltin(value,render=true){const revision=++builtinSelectionRevision;builtinSelection=value;try{if(value==='system'){AppState.customFontFamily=null}else{const f=BUILTIN_FONTS.find(f=>'builtin:'+f.file===value);if(!f)return;if(!builtinFaces.has(f.file)){const face=new FontFace(f.family,'url("fonts/'+encodeURIComponent(f.file)+'")');builtinFaces.set(f.file,face.load().then(loaded=>{document.fonts.add(loaded);return loaded}).catch(e=>{builtinFaces.delete(f.file);throw e}))}await builtinFaces.get(f.file);if(revision!==builtinSelectionRevision)return;AppState.customFontFamily=JSON.stringify(f.family)}try{localStorage.setItem('icaviot-builtin-font',value)}catch{}els.fontChoice.value=value;if(render&&(AppState.text||'').trim())await applyTextDesign()}catch{toast('This font could not load. Choose another font or try again.','error')}}
els.fontChoice.addEventListener('change',()=>{const value=els.fontChoice.value;if(value.startsWith('builtin:')||value==='system')chooseBuiltin(value);else{builtinSelection='';builtinSelectionRevision++;try{localStorage.removeItem('icaviot-builtin-font')}catch{}}});
const beforeBuiltinRestore=restoreCustomFont;restoreCustomFont=async function(){await beforeBuiltinRestore();if(!customFontRecords.length)updateCustomFontUi();let selected;try{selected=localStorage.getItem('icaviot-builtin-font')}catch{}if(selected)await chooseBuiltin(selected);else if(!customFontRecords.length){const plain=BUILTIN_FONTS.find(f=>f.name==='Blockletter');if(plain)await chooseBuiltin('builtin:'+plain.file);}};
const beforeBuiltinClear=clearCustomFont;clearCustomFont=async function(){builtinSelection='system';await beforeBuiltinClear();await chooseBuiltin('system')};
updateCustomFontUi();

els.fontChoice.addEventListener('change',()=>{if(/^\d+$/.test(els.fontChoice.value)){builtinSelection='';builtinSelectionRevision++;try{localStorage.removeItem('icaviot-builtin-font')}catch{}}},true);

const beforeBuiltinUpload=loadCustomFontFiles;loadCustomFontFiles=async function(files){if(Array.from(files||[]).some(f=>/\.(ttf|otf|woff2?)$/i.test(f.name))){builtinSelection='';builtinSelectionRevision++;try{localStorage.removeItem('icaviot-builtin-font')}catch{}}return beforeBuiltinUpload(files)};
